package main

import (
	"bufio"
	"fmt"
	"os"
)

const (
	MAX = 511
	MOD = 998244353
	INV = 499122177
)

func add(a, b int) int {
	a += b
	if a >= MOD {
		a -= MOD
	}
	return a
}

func mult(a, b int) int {
	return int((int64(a) * int64(b)) % MOD)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(in, &n, &k)
	if n == 1 {
		fmt.Println(0)
		return
	}
	limit := min(k, n)
	dp := make([][]int, MAX)
	for i := range dp {
		dp[i] = make([]int, MAX)
	}
	dp[1][1] = 2
	for pos := 0; pos < n; pos++ {
		ndp := make([][]int, MAX)
		for i := range ndp {
			ndp[i] = make([]int, MAX)
		}
		for i := 1; i <= limit; i++ {
			for j := 1; j <= limit; j++ {
				val := dp[i][j]
				if val == 0 {
					continue
				}
				nm := i
				if j+1 > nm {
					nm = j + 1
				}
				ndp[nm][j+1] = add(ndp[nm][j+1], val)
				ndp[i][1] = add(ndp[i][1], val)
			}
		}
		if pos != n-1 {
			dp = ndp
		}
	}
	nums := make([]int, MAX)
	for i := 1; i <= limit; i++ {
		for j := 1; j <= limit; j++ {
			nums[i] = add(nums[i], dp[i][j])
		}
	}
	div2 := make([]int, MAX)
	for i := 1; i <= n; i++ {
		div2[i] = mult(nums[i], INV)
	}
	res := 0
	for i := 1; i <= limit; i++ {
		for j := 1; j <= limit; j++ {
			if i*j < k {
				res = add(res, mult(2, mult(div2[i], div2[j])))
			}
		}
	}
	fmt.Println(res)
}

